fs::path Components::path(std::string_view name)const{for(auto&s:catalog())if(s.name==name)return directory_/wide(s.path);throw std::runtime_error("未知组件。");}
bool Components::ready(std::string_view name)const{auto p=path(name);if(!fs::exists(p))return false;for(auto&s:catalog())if(s.name==name)return !s.sha256.empty()&&file_hash(p)==s.sha256;return false;}
fs::path Components::require(std::string_view name)const{if(!ready(name))throw std::runtime_error("组件缺失或校验失败，请下载或修复："+std::string(name));return path(name);}
