 for(auto&s:catalog()){if(cancel)throw std::runtime_error("下载已取消。");if(ready(s.name)){progress(s.name+" 已校验");continue;}if(!s.url.empty()){auto temp=stage/wide(s.name+".exe");download(s.url,temp,s.sha256,progress,cancel);publish_file(temp,path(s.name));}}
 if(!ready("winscp")){auto zip=stage/L"WinSCP.zip";download("https://downloads.sourceforge.net/project/winscp/WinSCP/6.7/WinSCP-6.7-Portable.zip",zip,"fef88545873aca4b353ac322b1e2702f2feadf30758b713f5fc7e2bed60f7662",progress,cancel);auto extracted=stage/L"winscp";expand_zip(zip,extracted);for(auto&f:fs::recursive_directory_iterator(extracted))if(f.is_regular_file()&&(f.path().filename()==L"WinSCP.exe"||f.path().filename()==L"WinSCP.com"||f.path().extension()==L".txt"))publish_file(f.path(),path("winscp").parent_path()/f.path().filename());if(!ready("winscp"))throw std::runtime_error("WinSCP 解压后校验失败。");}
 if(!ready("terminal")){auto zip=stage/L"Terminal.zip";download("https://github.com/microsoft/terminal/releases/download/v1.24.12741.0/Microsoft.WindowsTerminal_1.24.12741.0_x64.zip",zip,"7aaa8321064c45d5af79205db13deb87f146f644bd8abdfae29f0155d7ce744e",progress,cancel);auto extracted=stage/L"terminal";expand_zip(zip,extracted);bool found=false;for(auto&f:fs::recursive_directory_iterator(extracted))if(f.is_regular_file()&&f.path().filename()==L"NOTICE.html")publish_file(f.path(),path("terminal").parent_path()/L"NOTICE.html");for(auto&f:fs::recursive_directory_iterator(extracted))if(f.is_regular_file()&&f.path().filename()==L"Microsoft.Terminal.Control.dll"){publish_file(f.path(),path("terminal"));found=true;}if(!found)throw std::runtime_error("终端归档缺少控件。");}
